let shopEnabled=false,shopCache=null,shopQuery='',shopCategory='Все',shopWishesOnly=false;
const shopPending=new Set();
const equipmentUpdates=new WeakMap();
let ownReviewCache=null,ownReviewPromise=null;
const $=id=>document.getElementById(id),preview=location.pathname.endsWith('/preview.html');let profile=null,user=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let initData='';
const ENDPOINT="https://script.google.com/macros/s/AKfycbxmGM6hwZ8pMmN2wys0kfk-LL687RxWHIiEv9Oo94aXVA9Fk84sMm3MaD7Po2TbMgpXTQ/exec";
async function api(path,method='GET',body){
 let action,extra=body||{};
 if(path.startsWith('/api/shipping/'))action=({own:'shippingOwn',save:'shippingSave',list:'shippingList',invite:'shippingInvite',adminSave:'shippingAdminSave',status:'shippingStatus'})[path.split('/').pop()];
 else if(path==='/api/shop/catalog')action='shopCatalog';
 else if(path==='/api/shop/wish')action='shopWish';
 else if(path==='/api/profile'){action=method==='PUT'?'save':'load';extra=method==='PUT'?{profile:body}:{};}
 else if(path.startsWith('/api/review/')){action=({'own':'reviewOwn','wish':'reviewWish','read':'reviewRead','save':'reviewSave','equipment':'equipmentSave','catalog':'equipmentCatalog','add':'equipmentOwnAdd','plan':'equipmentPlan','dispatch':'equipmentDispatch','counts':'equipmentOwnCounts','invite':'equipmentInvite','remove':'equipmentRemove','restore':'equipmentRestore','visit':'reviewVisit','check':'reviewCheck'})[path.split('/').pop()];}
 else if(path==='/api/monthly/team'){action='monthlyTeam';}
 else if(path==='/api/monthly/athlete'){action='monthlyAthlete';}
 else if(path==='/api/monthly/own'){action='monthlyOwn';}
 else if(path==='/api/followers')action='followersSave';
 else if(path==='/api/highlights')action='highlightSave';
 else if(path==='/api/admin/highlights')action='adminHighlights';
 else if(path==='/api/admin/users')action='adminUsers';
 else if(path==='/api/admin/level')action='adminSetLevel';
 else if(path==='/api/admin/delete')action='adminDeleteProfile';
 else if(path==='/api/admin/restore')action='adminRestoreProfile';
 else if(path==='/api/admin/role')action='adminSetRole';
 else if(path==='/api/admin/activate')action='activateAdmin';
 else if(path==='/api/publications')action=method==='POST'?'submit':'publications';
 else if(path.startsWith('/api/ranking')){action='ranking';extra={level:new URL(path,location.href).searchParams.get('level')||'all'};}
 else if(path.startsWith('/api/athletes/')){action='athlete';extra={id:decodeURIComponent(path.split('/').pop())};}
 else throw Error('Неизвестный запрос');
 const start=performance.now();
 const r=await fetch(ENDPOINT,{method:'POST',credentials:'omit',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,initData,...extra}),signal:AbortSignal.timeout(action==='submit'?45000:25000)});
 if(!r.ok)throw Error('Сервер недоступен. Попробуйте ещё раз.');
 const data=await r.json();if(!data.ok)throw Error(data.error||'Не удалось выполнить запрос.');
 $('status').textContent='Обновлено · '+((performance.now()-start)/1000).toFixed(1)+' сек.';return data;
}
