const BRAND_KEY={VK:'vk',Instagram:'instagram',TikTok:'tiktok',Telegram:'telegram',YouTube:'youtube',MAX:'max'};
function brandIcon(platform){const key=BRAND_KEY[platform];return key?`<span class="brand-icon brand-${key}" title="${esc(platform)}"><img src="data:image/svg+xml,${encodeURIComponent(BRAND_SVG[key])}" alt="${esc(platform)}"></span>`:'<span class="brand-icon brand-unknown" aria-label="Ссылка">↗</span>';}
const KINDS={publication:'Публикация',story:'История',video:'Видео',photo:'Фото',reels:'Reels',clip:'Клип',shorts:'Shorts',collection:'Подборка историй'};
function platformFromUrl(raw){try{const host=new URL(raw).hostname.replace(/^www\./,'');return host==='instagram.com'?'Instagram':['tiktok.com','vt.tiktok.com','vm.tiktok.com'].includes(host)?'TikTok':['vk.com','vk.ru','m.vk.com','m.vk.ru','vkvideo.ru'].includes(host)?'VK':host==='t.me'?'Telegram':['youtube.com','m.youtube.com','youtu.be'].includes(host)?'YouTube':host==='max.ru'?'MAX':'';}catch{return '';}}
function linkKind(item){if(KINDS[item.kind])return KINDS[item.kind];try{const u=new URL(item.url),p=u.pathname,platform=item.platform||platformFromUrl(item.url);if(platform==='Instagram')return /^\/stories\//.test(p)?'История':/^\/(reel|reels)\//.test(p)?'Reels':/^\/tv\//.test(p)?'Видео':'Публикация';if(platform==='VK')return /^\/clip-?\d+_/.test(p)?'Клип':/^\/video-?\d+_/.test(p)?'Видео':/^\/story-?\d+_/.test(p)?'История':'Публикация';if(platform==='TikTok')return /\/video\//.test(p)?'Видео':/\/photo\//.test(p)?'Фото':'Публикация';if(platform==='YouTube')return /^\/shorts\//.test(p)?'Shorts':p==='/watch'||/^\/embed\//.test(p)||u.hostname==='youtu.be'?'Видео':'Публикация';if(platform==='Telegram'&&/^\/[^/]+\/s\/\d+/.test(p))return 'История';}catch{}return 'Публикация';}
function statusMark(status,count){const options={accepted:['✓','Принято'],duplicate:['↻','Уже отправлено'],invalid:['×','Не принято']};const [mark,label]=options[status]||options.invalid;return `<span class="status-mark ${status}" title="${label}" role="img" aria-label="${label}${count!==undefined?': '+count:''}"><span aria-hidden="true">${mark}</span>${count!==undefined?`<b aria-hidden="true">${count}</b>`:''}</span>`;}
function resultCard(item){const label={accepted:'Принято',duplicate:'Повтор',invalid:'Не принято'}[item.status]||'Не принято';return `<div class="submission-result">${statusMark(item.status)}<span class="result-label">${label}</span><span class="result-url" title="${esc(item.url)}">${esc(item.url)}</span>${item.message?`<p class="result-reason">${esc(item.message)}</p>`:''}</div>`;}
let currentTab='profile',publicationCache=null,rankingCache=new Map(),filter='all',rankingMode='publications',monthlyMonth='',monthlyCache=new Map(),ownMonthlyCache=new Map(),ownMonths=[],publicationMonth='all';
function shell(tab){if(tab!=='shipping')document.body.classList.remove('shipping-screenshot');currentTab=tab;$('screen').innerHTML=`<nav class="tabs">${[['profile','Мой профиль'],['publications','Мои публикации'],['ranking','Рейтинг']].concat(shopEnabled?[['shop','Магазин']]:[]).concat(isAdmin?[['monthly','Разбор месяца'],['shipping','Отправка'],['users','Участники'],['admin','Популярные']]:[]).map(([key,label])=>`<button data-tab="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}</nav><div id="work-save-status" role="status"></div><div id="content"></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));queueMicrotask(syncWorkStatus);}
