function profileMarkup(a,own=false){return `<section class="panel center profile-identity">${photoMarkup(a)}<h1>${esc(a.name)}</h1><p>${esc([a.sport,a.city].filter(Boolean).join(' · '))}</p><div class="info">${esc(a.bio)}</div>${!own?contactMarkup(a):''}${own?'<div class="actions center-actions"><button id="edit" class="secondary">Изменить профиль</button></div>':a.links!==undefined?`<p>Уровень ${esc(a.level)} · ${numberText(a.links)} публикаций${a.rank?' · место по публикациям '+a.rank:''}</p>`:''}</section>${own?'':publicSocialLinks(a.socials||{})}`;}
