  const count=status=>results.filter(x=>x.status===status).length;
  $('results').innerHTML=`<div class="result-totals" aria-label="Итог отправки">${statusMark('accepted',count('accepted'))}${statusMark('duplicate',count('duplicate'))}${statusMark('invalid',count('invalid'))}</div>`+results.map(resultCard).join('');
