function sortedRanking(items,mode){const key=mode==='followers'?'followersTotal':'links',secondary=mode==='followers'?'links':'followersTotal';return [...items].sort((a,b)=>Number(b[key]||0)-Number(a[key]||0)||Number(b[secondary]||0)-Number(a[secondary]||0)||a.name.localeCompare(b.name,'ru')||a.id.localeCompare(b.id)).map((a,i)=>({...a,rank:i+1}));}
