async function openAthlete(id){const dialog=document.createElement('dialog');dialog.innerHTML='<button class="secondary close">Закрыть</button><div class="athlete">'+loading()+'</div>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();try{const {athlete}=preview?{athlete:(adminUsersCache?.items||[]).find(a=>a.id===id)||(rankingCache.get('all')?.items||[]).find(a=>a.id===id)}:await api('/api/athletes/'+encodeURIComponent(id));if(!athlete)throw Error('Профиль не найден.');const member={...athlete,id,level:athlete.level||'0'};
 const render=()=>{dialog.querySelector('.athlete').innerHTML=profileMarkup(member)+(isAdmin?'<div class="profile-admin-actions"><button class="secondary compact-level" data-profile-level>Изменить уровень</button><span class="small-note" role="status" data-level-feedback></span></div>':'');wirePhotos(dialog);wireContacts(dialog);const button=dialog.querySelector('[data-profile-level]');if(button)button.onclick=()=>memberLevelDialog(member,level=>{member.level=level;render();dialog.querySelector('[data-level-feedback]').textContent='Уровень изменён';});};render();
 }catch(e){dialog.querySelector('.athlete').textContent='Не удалось открыть профиль. '+e.message;}}
const PLATFORMS=['Instagram','TikTok','VK','Telegram','MAX','YouTube'];
const SOCIAL_EXAMPLES={Instagram:'@your_name или ссылка',TikTok:'@your_name или ссылка',VK:'https://vk.ru/your_name',Telegram:'https://t.me/your_name',MAX:'https://max.ru/your_name',YouTube:'https://youtube.com/@your_name'};
let stats=null,followers=[],highlights=[],isAdmin=false,isOwner=false,adminUsersCache=null,canActivateAdmin=false,adminHighlightsCache=null,avatarDraft='';
const numberText=n=>n===null||n===undefined?'—':Number(n).toLocaleString('ru-RU');
function monthText(value){try{return new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric',timeZone:'Asia/Yekaterinburg'}).format(new Date(value+'-01T12:00:00Z')).replace(' г.','');}catch{return value;}}
function photoMarkup(a,small=false){const initials=String(a.name||'UP').split(/\s+/).slice(0,2).map(x=>x[0]).join('');const photo=a.photo||a.avatar||a.telegramPhoto||'';const safe=/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(photo)||/^https:\/\/(?:t\.me|telegram\.org|[a-z0-9-]+\.telegram\.org)\/[^\s<>"\\]+$/i.test(photo);return `<div class="avatar athlete-avatar ${small?'small-avatar':''}"><span>${esc(initials)}</span>${safe?`<img class="athlete-photo" src="${esc(photo)}" alt="${esc(a.name||'Фото спортсмена')}" referrerpolicy="no-referrer">`:''}</div>`;}
function wirePhotos(root=document){root.querySelectorAll('.athlete-photo').forEach(img=>img.onerror=()=>img.remove());}
function statsMarkup(){const value=stats||{month:new Date().toISOString().slice(0,7),monthPublications:0,total:(publicationCache||[]).length,rank:null,level:'0'};return `<section class="mini-stats" aria-label="Статистика профиля"><div><b>${numberText(value.monthPublications)}</b><span>Публикаций · ${esc(monthText(value.month))}</span></div><div><b>${value.rank?'#'+value.rank:'—'}</b><span>Место в общем рейтинге</span></div><div><b>${esc(value.level)}</b><span>Уровень</span></div><div><b>${numberText(value.total)}</b><span>Публикаций за всё время</span></div></section>`;}
function followerAction(item,month){if(item.count===null||item.count===undefined)return 'Указать подписчиков';if(item.current===null||item.current===undefined||item.month!==month)return 'Обновить за '+monthText(month);return 'Изменить число';}
function socialMarkup(items,editable=false){if(!items.length)return editable?'<section class="panel"><h2>Социальные сети</h2><p>Добавьте ссылки на свои аккаунты. Затем здесь можно будет указать подписчиков.</p><button class="secondary" id="add-socials">Добавить соцсети</button></section>':'';const month=stats?.month||new Date().toISOString().slice(0,7);return `<section class="panel"><div class="section-heading"><h2>Социальные сети</h2>${editable?'<button class="secondary" id="add-socials">Добавить соцсеть</button>':''}</div>${editable&&currentTab!=='followers'?'<button class="secondary compact-level" id="open-followers">Обновить подписчиков</button>':''}<div class="social-grid">${items.map(item=>{const delta=item.delta===null||item.delta===undefined?'Нет сравнения с прошлым месяцем':(item.delta>0?'+':'')+numberText(item.delta)+' за месяц';const label=item.month?monthText(item.month):'Ещё не указано';return `<div class="social-card"><a class="social-account" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${brandIcon(item.platform)}<span>${esc(item.platform)} ↗</span></a>${item.count===null||item.count===undefined?'':`<b class="public-follower-count">${numberText(item.count)}</b><small>подписчиков · ${esc(label)}</small>`}${editable?`<button class="secondary follower-action" data-followers="${esc(item.platform)}">${esc(followerAction(item,month))}</button>`:''}<span class="follower-delta ${item.delta>0?'up':item.delta<0?'down':''}">${esc(delta)}</span></div>`;}).join('')}</div>${editable?'<p class="small-note">Числа вводятся вручную. Отчёт за текущий месяц можно уточнять; предыдущие месяцы сохраняются.</p>':''}</section>`;}
function wireFollowers(){if($('add-socials'))$('add-socials').onclick=form;if($('open-followers'))$('open-followers').onclick=showFollowerScreen;document.querySelectorAll('[data-followers]').forEach(b=>b.onclick=()=>followerDialog(b.dataset.followers));}
function showFollowerScreen(){if(!profile)return form();shell('followers');$('content').innerHTML=`<section class="panel"><h1>Обновить подписчиков</h1><p>Отчёт за ${esc(monthText(stats?.month))}. Укажите количество подписчиков на сегодняшний день в каждой своей соцсети.</p><button class="secondary compact-level" id="back-profile">Мой профиль</button></section>${socialMarkup(followers,true)}<p id="followers-saved" role="status"></p>`;$('back-profile').onclick=card;wireFollowers();}
function followerLanding(){const route=preview?new URLSearchParams(location.search).get('startapp'):new URLSearchParams(initData).get('start_param');if(route==='shipping')showShippingForm();else if(route==='followers')showFollowerScreen();else if(route==='equipment')showEquipmentScreen();else card();}
function ownHighlightsMarkup(){return `<section class="panel"><div class="section-heading"><h2>Сильные публикации</h2><button id="add-highlight" class="secondary">Добавить</button></div><p class="small-note">Покажи публикацию, которой гордишься. Просмотры, лайки и комментарии вводятся вручную и будут видны администратору. Этот отчёт не добавляет ссылку повторно в общий счётчик.</p>${highlights.length?highlights.map((item,i)=>highlightMarkup(item,false,i)).join(''):'<p>Пока нет выделенных публикаций.</p>'}</section>`;}
function highlightMarkup(item,admin=false,index=0){return `<article class="highlight-card">${admin?`<div class="highlight-athlete">${photoMarkup(item.athlete,true)}<b>${esc(item.athlete.name)}</b></div>`:''}<div class="post-heading">${brandIcon(item.platform)}<span class="post-kind">${esc(linkKind(item))}</span>${!admin?`<button class="plain-button" data-highlight="${index}">Изменить</button>`:''}</div><a class="publication" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.url)}</a><div class="engagement"><span><b>${numberText(item.views)}</b> просмотров</span><span><b>${numberText(item.likes)}</b> лайков</span><span><b>${numberText(item.comments)}</b> комментариев</span></div><small class="small-note">Обновлено ${esc(new Date(item.updatedAt).toLocaleDateString('ru-RU'))}</small></article>`;}
function myProfile(){shell('profile');const shown={...profile,photo:profile.photo||profile.avatar||profile.telegramPhoto||user?.photoUrl};$('content').innerHTML=profileMarkup(shown,true)+statsMarkup()+socialMarkup(followers,true)+'<div id="profile-review-cards"></div>'+ownHighlightsMarkup()+(isOwner?'<section class="panel"><h2>Заполнение экипировки</h2><p class="small-note">Ссылка открывает каталог, где спортсмен отмечает свою экипировку.</p><button class="secondary compact-level" id="equipment-invitation">Отправить ссылку для заполнения</button></section>':'')+(canActivateAdmin?'<section class="panel"><h2>Управление командой</h2><p>Ваш аккаунт подготовлен для роли главного администратора.</p><button id="activate-admin" class="secondary">Активировать администратора</button></section>':'');$('edit').onclick=form;if($('equipment-invitation'))$('equipment-invitation').onclick=equipmentInvitation;loadProfileReviewCards();wireFollowers();$('add-highlight').onclick=()=>highlightDialog();document.querySelectorAll('[data-highlight]').forEach(b=>b.onclick=()=>highlightDialog(highlights[Number(b.dataset.highlight)]));if($('activate-admin'))$('activate-admin').onclick=adminDialog;wirePhotos();}
function form(){const a=profile||{};avatarDraft=a.avatar||'';const photo={name:a.name||user?.name,photo:avatarDraft||a.telegramPhoto||user?.photoUrl};$('screen').innerHTML=`<section class="panel"><h1>${profile?'Изменить профиль':'Регистрация спортсмена'}</h1><form id="profile"><div class="photo-editor"><div id="photo-preview">${photoMarkup(photo)}</div><p class="small-note">По умолчанию используем фото, которое передал Telegram.</p><label class="file-button" for="photo-input">Выбрать другое фото</label><input type="file" id="photo-input" accept="image/*" class="visually-hidden"><button type="button" id="telegram-photo" class="plain-button">Использовать фото Telegram</button><p id="photo-error" role="alert"></p></div><label for="name">Фамилия и имя</label><input id="name" required minlength="2" maxlength="120" value="${esc(a.name||user?.name||'')}"><label for="sport">Вид спорта</label><input id="sport" maxlength="100" value="${esc(a.sport||'')}"><label for="city">Город</label><input id="city" maxlength="100" value="${esc(a.city||'')}"><label for="bio">О себе и достижения</label><textarea id="bio" maxlength="500">${esc(a.bio||'')}</textarea><details ${profile?'open':''}><summary>Социальные сети — необязательно</summary><p class="small-note">Можно зарегистрироваться без единой ссылки и добавить соцсети позже через «Изменить профиль». Instagram и TikTok: введите @username или полную ссылку. Остальные соцсети: ссылку на профиль. Ненужные поля оставьте пустыми.</p>${PLATFORMS.map(platform=>`<label class="social-edit-label" for="social-${platform}">${brandIcon(platform)} ${esc(platform)}</label><input id="social-${platform}" type="${['Instagram','TikTok'].includes(platform)?'text':'url'}" autocapitalize="off" spellcheck="false" maxlength="500" placeholder="${SOCIAL_EXAMPLES[platform]}" value="${esc(a.socials?.[platform]||'')}">`).join('')}</details><div id="profile-error" role="alert"></div><div class="actions"><button id="save">${profile?'Сохранить':'Зарегистрироваться'}</button>${!profile?'<button type="submit" formnovalidate id="skip-socials" class="secondary">Зарегистрироваться без соцсетей</button>':''}${profile?'<button type="button" id="cancel" class="secondary">Отмена</button>':''}</div></form></section>`;$('profile').onsubmit=save;if($('cancel'))$('cancel').onclick=card;$('photo-input').onchange=selectPhoto;$('telegram-photo').onclick=()=>{avatarDraft='';$('photo-preview').innerHTML=photoMarkup({name:a.name||user?.name,photo:a.telegramPhoto||user?.photoUrl});wirePhotos();};wirePhotos();}
async function selectPhoto(e){const file=e.target.files[0];if(!file)return;$('photo-error').textContent='';$('save').disabled=true;try{if(file.size>12*1024*1024)throw Error('Выберите фото размером до 12 МБ.');const url=URL.createObjectURL(file);let image;try{image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Не удалось прочитать фото. Попробуйте JPEG или PNG.'));img.src=url;});}finally{URL.revokeObjectURL(url);}const canvas=document.createElement('canvas'),size=192;canvas.width=canvas.height=size;const side=Math.min(image.naturalWidth,image.naturalHeight);if(!side)throw Error('Пустое изображение.');const context=canvas.getContext('2d');context.fillStyle='#191b20';context.fillRect(0,0,size,size);context.drawImage(image,(image.naturalWidth-side)/2,(image.naturalHeight-side)/2,side,side,0,0,size,size);let data='';for(const quality of [.8,.65,.5,.35]){data=canvas.toDataURL('image/jpeg',quality);if(data.length<=22000)break;}if(data.length>22000)throw Error('Фото слишком сложное для загрузки. Выберите другое.');avatarDraft=data;$('photo-preview').innerHTML=photoMarkup({name:$('name').value,photo:data});wirePhotos();}catch(err){$('photo-error').textContent=err.message;}finally{$('save').disabled=false;}}
async function save(e){e.preventDefault();$('save').disabled=true;if($('skip-socials'))$('skip-socials').disabled=true;const next={avatar:avatarDraft,socials:{}};for(const k of ['name','sport','city','bio'])next[k]=$(k).value.trim();if(e.submitter?.id!=='skip-socials')for(const platform of PLATFORMS){const value=$('social-'+platform).value.trim();if(value)next.socials[platform]=value;}try{for(const platform of ['Instagram','TikTok'])if(next.socials[platform])next.socials[platform]=socialInputUrl(platform,next.socials[platform]);if(preview){profile={...next,photo:next.avatar||profile?.telegramPhoto||''};followers=PLATFORMS.filter(p=>next.socials[p]).map(platform=>({platform,url:next.socials[platform],count:null,delta:null}));}else{const data=await api('/api/profile','PUT',next);profile=data.profile;stats=data.stats;followers=data.followers;}rankingCache.clear();$('status').textContent=preview?'Макет: изменения только на этом экране.':'Профиль сохранён.';followerLanding();}catch(err){$('status').textContent='Не удалось сохранить. '+err.message;$('profile-error').textContent=err.message;$('save').disabled=false;if($('skip-socials'))$('skip-socials').disabled=false;}}
function dialogShell(title,body){const dialog=document.createElement('dialog');dialog.className='feature-dialog';dialog.innerHTML=`<button type="button" class="secondary close">Закрыть</button><h2>${esc(title)}</h2>${body}<p class="dialog-error" role="alert"></p>`;document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();return dialog;}
function followerDialog(platform){const item=followers.find(x=>x.platform===platform);if(!item)return;const month=stats?.month||new Date().toISOString().slice(0,7);const d=dialogShell(platform+' · подписчики',`<p>Отчёт за ${esc(monthText(month))}. ${item.previous===null||item.previous===undefined?'За прошлый месяц пока нет отчёта.':'В прошлом месяце: '+numberText(item.previous)+'.'}</p><form><label for="follower-number">Сколько подписчиков сейчас?</label><input id="follower-number" type="number" inputmode="numeric" required min="0" max="10000000000" step="1" value="${item.current??''}"><div class="actions"><button>Сохранить отчёт</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=d.querySelector('form button:not([type="button"])');button.disabled=true;try{if(preview)throw Error('Отчёт сохраняется только внутри Telegram.');const data=await api('/api/followers','POST',{platform,count:Number(d.querySelector('input').value)});followers=data.followers;if(data.month&&stats)stats.month=data.month;rankingCache.clear();d.close();if(currentTab==='followers'){showFollowerScreen();$('followers-saved').textContent='Количество подписчиков сохранено.';}else if(currentTab==='profile')card();}catch(err){d.querySelector('.dialog-error').textContent=err.message;button.disabled=false;}};}
function highlightDialog(item){const d=dialogShell(item?'Статистика публикации':'Сильная публикация',`<p>Укажите публикацию и её текущие показатели. Эти данные вводятся вручную.</p><form><label for="highlight-url">Ссылка на публикацию</label><input id="highlight-url" type="url" required maxlength="2048" value="${esc(item?.url||'')}" ${item?'readonly':''}>${[['views','Просмотры'],['likes','Лайки'],['comments','Комментарии']].map(([key,label])=>`<label for="highlight-${key}">${label}</label><input id="highlight-${key}" type="number" inputmode="numeric" min="0" max="1000000000000" step="1" required value="${item?.[key]??''}">`).join('')}<div class="actions"><button>Отправить статистику</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=d.querySelector('form button:not([type="button"])');button.disabled=true;try{if(preview)throw Error('Статистика сохраняется только внутри Telegram.');const body={url:d.querySelector('#highlight-url').value.trim()};for(const key of ['views','likes','comments'])body[key]=Number(d.querySelector('#highlight-'+key).value);const data=await api('/api/highlights','POST',body);highlights=data.items;adminHighlightsCache=null;d.close();if(currentTab==='profile')card();}catch(err){d.querySelector('.dialog-error').textContent=err.message;button.disabled=false;}};}
async function showAdminHighlights(){if(!adminHighlightsCache)adminHighlightsCache=(await api('/api/admin/highlights')).items;if(currentTab!=='admin')return;$('content').innerHTML=`<section class="panel"><div class="section-heading"><h1>Популярные публикации</h1><button id="refresh-highlights" class="secondary">Обновить</button></div><p class="small-note">Отчёты спортсменов, отсортированные по просмотрам. Показатели внесены вручную, автоматической проверки содержания нет.</p>${adminHighlightsCache.length?adminHighlightsCache.map(item=>highlightMarkup(item,true)).join(''):'<p>Спортсмены ещё не выделили публикации.</p>'}</section>`;$('refresh-highlights').onclick=()=>{adminHighlightsCache=null;navigate('admin');};wirePhotos();}
function adminDialog(){const d=dialogShell('Активация администратора','<p>Введите одноразовый код владельца проекта. Он действует только для подготовленного Telegram-аккаунта.</p><form><label for="admin-code">Одноразовый код</label><input id="admin-code" type="password" required autocomplete="one-time-code" autocapitalize="off" spellcheck="false"><div class="actions"><button>Активировать</button></div></form>');d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('form button');b.disabled=true;try{await api('/api/admin/activate','POST',{code:d.querySelector('input').value.trim()});isAdmin=true;isOwner=true;canActivateAdmin=false;d.close();card();}catch(err){d.querySelector('.dialog-error').textContent=err.message;b.disabled=false;}};}

