async function showAdminUsers(){
 if(!adminUsersCache)adminUsersCache=await api('/api/admin/users');if(currentTab!=='users')return;
 const data={...adminUsersCache,items:showDeletedUsers?(adminUsersCache.archived||[]):adminUsersCache.items};$('content').innerHTML=`<section class="panel"><div class="section-heading"><h1>${showDeletedUsers?'Удалённые':'Участники'} · ${data.items.length}</h1><button class="secondary" id="refresh-users">Обновить</button></div><p>Все зарегистрированные спортсмены, в том числе без публикаций. ${data.isOwner?'Вы — главный администратор. Можно назначать и снимать администраторов.':'Назначать администраторов может только главный администратор.'}</p>${data.isOwner?'<div class="filters"><button id="active-users">Участники</button><button id="deleted-users" class="secondary">Удалённые</button></div>':''}<label for="user-search">Поиск по имени, спорту или городу</label><input id="user-search" type="search" placeholder="Найти участника"><div id="user-list"></div></section>`;
 const render=()=>{const q=$('user-search').value.trim().toLocaleLowerCase('ru');const items=data.items.filter(a=>[a.name,a.sport,a.city].join(' ').toLocaleLowerCase('ru').includes(q));$('user-list').innerHTML=items.map(a=>`<article class="highlight-card"><div class="highlight-athlete">${photoMarkup(a,true)}<b>${esc(a.name)}${a.isSelf?' · Вы':''}</b></div><p>${esc([a.sport,a.city].filter(Boolean).join(' · '))}</p><p>${a.isOwner?'Главный администратор':a.isAdmin?'Администратор':'Спортсмен'} · ${esc(memberLevelText(a.level))} · Публикаций: ${numberText(a.links)}</p><div class="actions">${a.deletedAt?`<button class="secondary" data-restore-id="${esc(a.id)}">Восстановить профиль</button>`:`<button class="secondary" data-user-profile="${esc(a.id)}">Профиль</button>${!a.isOwner||data.isOwner?`<button class="secondary" data-level-id="${esc(a.id)}">Изменить уровень</button>`:''}`}${data.isOwner&&!a.isOwner&&!a.deletedAt?`<button class="secondary" data-role-id="${esc(a.id)}">${a.isAdmin?'Снять администратора':'Назначить администратором'}</button><button class="danger-outline" data-delete-id="${esc(a.id)}">Удалить профиль</button>`:''}</div></article>`).join('')||'<p>Участники не найдены.</p>';document.querySelectorAll('[data-user-profile]').forEach(b=>b.onclick=()=>openAthlete(b.dataset.userProfile));document.querySelectorAll('[data-role-id]').forEach(b=>b.onclick=()=>roleDialog(data.items.find(a=>a.id===b.dataset.roleId)));document.querySelectorAll('[data-level-id]').forEach(b=>b.onclick=()=>memberLevelDialog(data.items.find(a=>a.id===b.dataset.levelId)));document.querySelectorAll('[data-delete-id]').forEach(b=>b.onclick=()=>memberDeleteDialog(data.items.find(a=>a.id===b.dataset.deleteId)));document.querySelectorAll('[data-restore-id]').forEach(b=>b.onclick=()=>memberRestoreDialog(data.items.find(a=>a.id===b.dataset.restoreId)));wirePhotos();};$('user-search').oninput=render;render();$('refresh-users').onclick=()=>{adminUsersCache=null;navigate('users');};if(data.isOwner){$('active-users').onclick=()=>{showDeletedUsers=false;showAdminUsers();};$('deleted-users').onclick=()=>{showDeletedUsers=true;showAdminUsers();};}
}
function roleDialog(athlete){const role=athlete.isAdmin?'athlete':'admin';const d=dialogShell(role==='admin'?'Назначить администратора':'Снять администратора',`<p><b>${esc(athlete.name)}</b></p><p>${role==='admin'?'Получит доступ ко всем участникам и отчётам команды. Назначать других администраторов сможет только главный администратор.':'Доступ к управлению командой будет закрыт. Профиль и публикации сохранятся.'}</p><form><button>${role==='admin'?'Подтвердить назначение':'Подтвердить снятие'}</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('form button');b.disabled=true;try{if(preview)throw Error('В макете права не изменяются.');adminUsersCache=await api('/api/admin/role','POST',{id:athlete.id,role});d.close();if(currentTab==='users')await showAdminUsers();}catch(err){d.querySelector('.dialog-error').textContent=err.message;b.disabled=false;}};}

function socialInputUrl(platform,value){if(/^https:\/\//i.test(value))return value;const name=value.replace(/^@/,'');if(!name||name.length>(platform==='Instagram'?30:24)||! /^[A-Za-z0-9_]+(?:[.][A-Za-z0-9_]+)*$/.test(name))throw Error(platform+': введите @username латинскими буквами, цифрами, точками или подчёркиваниями, либо полную ссылку.');return platform==='Instagram'?'https://instagram.com/'+name:'https://tiktok.com/@'+name;}

function publicSocialLinks(socials){const items=PLATFORMS.filter(p=>socials[p]);if(!items.length)return '';return `<section class="panel public-socials"><h2>Социальные сети</h2><div class="social-links">${items.map(p=>`<a href="${esc(socials[p])}" class="social-link" target="_blank" rel="noopener noreferrer" aria-label="Открыть ${esc(p)}">${brandIcon(p)}<span>${esc(p)}</span><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`;}

let showDeletedUsers=false;
const MEMBER_LEVELS=[['0','Уровень 0'],['1','Уровень 1'],['2','Уровень 2'],['3','Уровень 3'],['Ambassador','Амбассадор']];
function memberLevelText(value){return MEMBER_LEVELS.find(([v])=>v===(value||'0'))?.[1]||'Уровень 0';}
function memberLevelDialog(member,onSaved){
 let chosen=member.level||'0';
 const d=dialogShell('Изменить уровень',`<p>${esc(member.name)}</p><form><div class="level-options" role="group" aria-label="Новый уровень">${MEMBER_LEVELS.map(([v,label])=>`<button type="button" data-pick-level="${v}" aria-pressed="${chosen===v}" class="${chosen===v?'':'secondary'}">${v==='Ambassador'?'Амбассадор':v}</button>`).join('')}</div><button type="submit">Сохранить</button></form>`);
 d.querySelectorAll('[data-pick-level]').forEach(b=>b.onclick=()=>{chosen=b.dataset.pickLevel;d.querySelectorAll('[data-pick-level]').forEach(x=>{x.classList.toggle('secondary',x.dataset.pickLevel!==chosen);x.setAttribute('aria-pressed',String(x.dataset.pickLevel===chosen));});});
 memberMutation(d,'/api/admin/level',()=>({id:member.id,level:chosen}),member,onSaved);
}
function memberDeleteDialog(member){
 const d=dialogShell('Удалить профиль',`<p><b>${esc(member.name)}</b></p><p>Профиль исчезнет из команды и рейтинга, вход будет закрыт. Данные можно восстановить из раздела «Удалённые». Права администратора будут сняты.</p><form><label for="delete-confirm">Для подтверждения введите: ${esc(member.name)}</label><input id="delete-confirm" required autocomplete="off" autocapitalize="off"><button class="danger-outline">Удалить профиль</button></form>`);
 memberMutation(d,'/api/admin/delete',()=>({id:member.id,confirmName:d.querySelector('input').value}),member);
}
function memberRestoreDialog(member){
 const d=dialogShell('Восстановить профиль',`<p>Вернуть профиль ${esc(member.name)} и его публикации? Права администратора при необходимости нужно назначить заново.</p><form><button>Восстановить профиль</button></form>`);
 memberMutation(d,'/api/admin/restore',()=>({id:member.id}),member);
}
function memberMutation(d,path,payload,member,onSaved){d.querySelector('form').onsubmit=async e=>{
 e.preventDefault();const button=d.querySelector('form button:not([type="button"])');button.disabled=true;
 if(path==='/api/admin/level'&&currentTab==='monthly'){const body={...payload(),compact:true};d.close();if(onSaved)onSaved(body.level);backgroundSave('Уровень',async()=>{await api(path,'POST',body);adminUsersCache=null;if(member.isSelf){if(profile)profile.level=body.level;if(stats)stats.level=body.level;}rankingCache.clear();for(const team of monthlyCache.values()){const a=team.items.find(x=>x.id===body.id);if(a)a.level=body.level;}},{id:body.id,name:member.name,path,payload:body});return;}
 try{if(preview)throw Error('В макете данные участников не изменяются.');const body=payload();adminUsersCache=await api(path,'POST',body);if(path==='/api/admin/level'&&member.isSelf){if(profile)profile.level=body.level;if(stats)stats.level=body.level;}rankingCache.clear();monthlyCache.clear();adminHighlightsCache=null;d.close();if(onSaved)onSaved(body.level);if(currentTab==='users')await showAdminUsers();else if(currentTab==='ranking')await showRanking();}
 catch(err){d.querySelector('.dialog-error').textContent=err.message;button.disabled=false;}
 };}

function contactMarkup(a){return /^https:\/\/t\.me\/[A-Za-z][A-Za-z0-9_]{3,31}$/.test(a.contactUrl||'')?`<a class="athlete-contact" href="${esc(a.contactUrl)}" data-telegram-contact>↗ Написать</a>`:'';}
