async function selectEquipmentInline(root,data,id,productId,onUpdated,catalogProduct){
 const product=catalogProduct||(data.equipment.wishProducts||[]).find(p=>p.id===productId);if(!product)return;
 if(currentTab==='monthly'){const month=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Yekaterinburg',year:'numeric',month:'2-digit'}).format(new Date()),requestId=reviewRequestId();const transform=d=>({...d,equipment:{...d.equipment,items:(d.equipment.items||[]).some(r=>r.productId===productId&&r.month===month)?d.equipment.items:[...(d.equipment.items||[]),{id:requestId,productId,item:product.title,state:'planned',month}]}});return queueReviewChange(root,data,id,transform,'plan',{id,productId,requestId,reviewMonth:monthlyMonth},onUpdated,()=>markMonthly(id,{assigned:true}));}

 let state=equipmentUpdates.get(root);if(!state){state={confirmed:data,pending:new Map(),queue:Promise.resolve()};equipmentUpdates.set(root,state);}
 const month=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Yekaterinburg',year:'numeric',month:'2-digit'}).format(new Date());
 if(state.pending.has(productId)||(state.confirmed.equipment.items||[]).some(r=>r.productId===productId&&r.month===month))return;
 const requestId=reviewRequestId();state.pending.set(productId,{id:'pending-'+requestId,productId,state:'planned',item:product.title,month});
 const render=()=>{const next={...state.confirmed,equipment:{...state.confirmed.equipment,items:[...(state.confirmed.equipment.items||[]),...state.pending.values()]}};onUpdated(next);const wishes=root.querySelector('.equipment-wishes');if(wishes)wishes.open=true;};render();
 const save=state.queue.then(async()=>{try{state.confirmed=await api('/api/review/plan','POST',{id,productId,requestId});state.pending.delete(productId);render();return true;}catch(e){state.pending.delete(productId);render();const error=root.querySelector('[data-wish-error]');if(error)error.textContent=e.message;return false;}finally{if(!state.pending.size)equipmentUpdates.delete(root);}});state.queue=save;return await save;
}

