function validEquipmentReview(data){return !!data&&Array.isArray(data.reviews)&&!!data.equipment&&Array.isArray(data.equipment.items)&&Array.isArray(data.equipment.sent)&&Array.isArray(data.equipment.decisions);}
async function readOwnEquipment(){
 if(validEquipmentReview(ownReviewCache))return ownReviewCache;
 ownReviewCache=null;
 // Retry only this read when a successful HTTP response has the wrong payload. Never retry a write.
 for(let attempt=0;attempt<2;attempt++){
  const result=await api('/api/review/own');
  if(validEquipmentReview(result)){ownReviewCache=result;return result;}
 }
 throw Error('Не удалось получить экипировку. Нажми «Повторить».');
}

const monthlyDetails=new Map(),monthlyReviews=new Map(),monthlyReviewLoads=new Map(),monthlyReviewStates=new Map();let monthlyOpenToken=0;const workJobs=[];let workTail=Promise.resolve();
function workBusy(){return workJobs.some(j=>j.state!=='saved');}
function workKey(){return user?.id?'up-work-v1:'+user.id:null;}
function persistWork(){try{const key=workKey();if(key)localStorage.setItem(key,JSON.stringify(workJobs.filter(j=>j.state!=='saved'&&j.meta).map(j=>({label:j.label,meta:j.meta,attempts:j.attempts||0,state:j.state}))));}catch(e){console.warn('Очередь не записана на устройство');}}
function workFailed(id){return workJobs.some(j=>j.meta?.id===id&&j.state==='failed');}
function syncWorkStatus(){persistWork();const pending=workJobs.filter(j=>['pending','retry','waiting'].includes(j.state)),failed=workJobs.filter(j=>j.state==='failed'),el=$('work-save-status');if(el){el.className=failed.length?'work-failed':pending.length?'work-pending':'work-saved';el.innerHTML=(pending.length?'● Сохраняем в фоне: '+pending.length+' ':'')+(failed.length?'Не сохранено: '+failed.map(j=>esc(j.meta?.name||'Спортсмен')+' — '+esc(j.label)).join(', ')+' <button id="work-retry" class="secondary compact-level">Повторить</button>':!pending.length&&workJobs.length?'✓ Сохранено':'');const retry=$('work-retry');if(retry)retry.onclick=()=>{for(const job of workJobs.filter(j=>j.state==='failed')){job.attempts=0;enqueueWork(job);}};}document.querySelectorAll('[data-month-athlete]').forEach(b=>b.classList.toggle('review-failed',workFailed(b.dataset.monthAthlete)));}
function enqueueWork(job){if(job.state==='pending')return;job.state='pending';syncWorkStatus();workTail=workTail.then(async()=>{const previous=workJobs.slice(0,workJobs.indexOf(job)).some(j=>j.state!=='saved'&&j.meta?.id===job.meta?.id);if(previous){job.state='waiting';job.error='Ожидает предыдущее изменение';syncWorkStatus();return;}try{await job.run();job.state='saved';for(const next of workJobs.filter(j=>j.state==='waiting'&&j.meta?.id===job.meta?.id))enqueueWork(next);}catch(e){job.error=e.message;job.attempts=(job.attempts||0)+1;const permanent=/ADMIN_ONLY|OWNER_|INVALID_|NOT_FOUND|PROFILE_DELETED/.test(e.message);if(!permanent&&job.attempts<4){job.state='retry';setTimeout(()=>enqueueWork(job),[2000,5000,10000][job.attempts-1]);}else job.state='failed';}syncWorkStatus();});return workTail;}
function backgroundSave(label,run,meta){const job={label,run,meta,state:'new',attempts:0};workJobs.push(job);persistWork();return enqueueWork(job);}
function restoreWork(){const key=workKey();if(!key||!isAdmin)return;try{const saved=JSON.parse(localStorage.getItem(key)||'[]');for(const entry of saved){const m=entry.meta;if(!m||!['/api/admin/level','/api/review/check','/api/review/save','/api/review/plan','/api/review/remove','/api/review/visit'].includes(m.path)||!m.payload||m.id!==m.payload.id)continue;if(m.path==='/api/review/check'){saveLocalCheck(m.id,m.payload.month,m.payload.platform,m.payload.checked);continue;}backgroundSave(entry.label,async()=>{await api(m.path,'POST',m.payload);monthlyReviews.delete(m.id);monthlyDetails.clear();},m);}persistWork();}catch(e){console.warn('Не удалось восстановить очередь');}}
function markMonthly(id,patch){const team=monthlyCache.get(monthlyMonth),a=team?.items.find(a=>a.id===id);if(a)Object.assign(a,patch);}
function queueReviewChange(root,data,id,transform,action,payload,onUpdated,onSuccess){let state=monthlyReviewStates.get(id);if(!state){state={confirmed:data,pending:new Map()};monthlyReviewStates.set(id,state);}state.onUpdated=onUpdated;const key=payload.requestId||reviewRequestId();state.pending.set(key,transform);const render=()=>{let next=state.confirmed;for(const apply of state.pending.values())next=apply(next);monthlyReviews.set(id,next);state.onUpdated(next);};render();return backgroundSave(action==='check'?'Отметка соцсети':action==='plan'?'Экипировка':'Разбор',async()=>{const result=await api('/api/review/'+action,'POST',payload);if(!validEquipmentReview(result))throw Error('Неполный ответ сервера');state.confirmed=result;state.pending.delete(key);render();if(onSuccess)onSuccess();},{id,name:monthlyCache.get(monthlyMonth)?.items.find(a=>a.id===id)?.name,path:'/api/review/'+action,payload});}
function wireGeneralReview(root,data,month,id,admin,onUpdated){if(!admin)return;root.querySelectorAll('[data-review-check]').forEach(b=>b.onchange=()=>{const platform=b.dataset.reviewCheck,checked=b.checked;saveLocalCheck(id,month,platform,checked);const next={...data,checks:{...data.checks,[month+':'+platform]:checked}};monthlyReviews.set(id,next);onUpdated(next);});const button=root.querySelector('[data-review-comment]');if(button)button.onclick=()=>{const r=data.reviews.find(r=>r.month===month&&r.platform==='Общий комментарий')||{},d=dialogShell('Комментарий · '+monthText(month),`<form><label>Личная заметка — только администраторам<textarea id="general-private" maxlength="2000">${esc(r.privateNote||'')}</textarea></label><label>Рекомендация спортсмену<textarea id="general-public" maxlength="2000">${esc(r.recommendation||'')}</textarea></label><button>Сохранить</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const note={month,platform:'Общий комментарий',privateNote:d.querySelector('#general-private').value.trim(),recommendation:d.querySelector('#general-public').value.trim()};d.close();queueReviewChange(root,data,id,v=>({...v,reviews:[...v.reviews.filter(r=>r.month!==month||r.platform!=='Общий комментарий'),note]}),'save',{...note,id,requestId:reviewRequestId()},onUpdated);};};}
function wireEquipmentRemoval(root,data,id,admin,onUpdated){if(!admin)return;root.querySelectorAll('[data-equipment-row]').forEach(row=>{let start;row.ontouchstart=e=>{start=e.touches[0].clientX;};row.ontouchend=e=>{if(start!==undefined&&start-e.changedTouches[0].clientX>45)row.classList.add('show-remove');else if(start!==undefined&&e.changedTouches[0].clientX-start>45)row.classList.remove('show-remove');};});root.querySelectorAll('[data-gear-remove]').forEach(b=>b.onclick=()=>{const itemId=b.dataset.gearRemove;if(!confirm('Удалить эту экипировку из списка спортсмена?'))return;queueReviewChange(root,data,id,d=>({...d,equipment:{...d.equipment,items:(d.equipment.items||[]).filter(r=>r.id!==itemId),sent:(d.equipment.sent||[]).filter(r=>r.id!==itemId),initialItems:(d.equipment.initialItems||[]).filter(r=>r.id!==itemId)}}),'remove',{id,itemId,requestId:reviewRequestId()},onUpdated);});}
