function monthlyReviewData(id){if(monthlyReviews.has(id))return Promise.resolve(monthlyReviews.get(id));if(!monthlyReviewLoads.has(id)){const promise=api('/api/review/read','POST',{id}).then(data=>{if(!validEquipmentReview(data))throw Error('Не удалось получить разбор');monthlyReviews.set(id,data);return data;}).finally(()=>monthlyReviewLoads.delete(id));monthlyReviewLoads.set(id,promise);}return monthlyReviewLoads.get(id);}

function saveLocalCheck(id,month,platform,checked){const key=(workKey()||'up-preview')+':checks';let values={};try{values=JSON.parse(localStorage.getItem(key)||'{}');values[id+':'+month+':'+platform]=!!checked;localStorage.setItem(key,JSON.stringify(values));}catch(e){throw Error('Не удалось сохранить отметку на устройстве');}}
function withLocalChecks(id,data){let checks={...data.checks};try{const values=JSON.parse(localStorage.getItem((workKey()||'up-preview')+':checks')||'{}');for(const [k,v] of Object.entries(values))if(k.startsWith(id+':'))checks[k.slice(id.length+1)]=v;}catch(e){}return {...data,checks};}

function localVisited(month,id){try{return !!JSON.parse(localStorage.getItem((workKey()||'up-preview')+':visits')||'{}')[month+':'+id];}catch(e){return false;}}

