 const cells=el.querySelectorAll('th,td');function editable(cell,read,write,numeric=false){if(shippingArchive)return;cell.tabIndex=0;cell.title='Дважды нажмите для изменения';const edit=()=>{if(cell.querySelector('input'))return;const input=document.createElement('input');input.className='shipment-inline-input';input.value=read();if(numeric){input.type='number';input.min='1';input.max='100';}cell.replaceChildren(input);input.focus();input.select();let done=false;const finish=()=>{if(done)return;done=true;const value=input.value.trim();if(numeric&&(!Number.isInteger(Number(value))||Number(value)<1||Number(value)>100)){done=false;input.focus();return;}write(value);cell.textContent=numeric?value+' шт.':value;save();};input.onblur=finish;input.onkeydown=e=>{if(e.key==='Enter')input.blur();if(e.key==='Escape'){done=true;cell.textContent=numeric?read()+' шт.':read();}};};cell.ondblclick=edit;cell.onkeydown=e=>{if(e.key==='Enter')edit();};if(fresh)cell.onclick=edit;}
 editable(cells[0],()=>r.fullName||r.name||'',v=>r.fullName=v);editable(cells[1],()=>r.address||'',v=>r.address=v);editable(cells[2],()=>r.phone||'',v=>r.phone=v);
 r.equipment.forEach((g,i)=>{editable(cells[3+i*2],()=>g.item+(g.size?', размер '+g.size:''),v=>{g.item=v;g.size='';});editable(cells[4+i*2],()=>String(g.quantity),v=>g.quantity=Number(v),true);});
